<?php
require __DIR__.'/../includes/bootstrap.php';require_permission('settings');$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$name=trim($_POST['store_name']??'');$desc=trim($_POST['store_description']??'');if($name==='')throw new RuntimeException('اسم المتجر مطلوب.');$logo=setting('store_logo');$hero=setting('hero_image');if(!empty($_FILES['store_logo']['name']))$logo=upload_store_image('store_logo');if(!empty($_FILES['hero_image']['name']))$hero=upload_store_image('hero_image');$q=db()->prepare('INSERT INTO store_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach(['store_name'=>$name,'store_description'=>$desc,'store_logo'=>$logo,'hero_image'=>$hero] as $k=>$v)$q->execute([$k,$v]);$msg='تم حفظ إعدادات المتجر.';}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>إعدادات المتجر</title><link rel="stylesheet" href="../assets/css/store.css"></head><body><main class="inner"><a href="index.php">← لوحة التحكم</a><h1>إعدادات المتجر</h1><?php if($msg):?><p class="notice"><?=h($msg)?></p><?php endif?><?php if($error):?><p class="notice"><?=h($error)?></p><?php endif?><form method="post" enctype="multipart/form-data" class="admin-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>اسم المتجر<input name="store_name" required value="<?=h(setting('store_name','الفخامة للشيشة والتبغ'))?>"></label><label>وصف المتجر<textarea name="store_description"><?=h(setting('store_description'))?></textarea></label><label>شعار المتجر<input type="file" name="store_logo" accept="image/jpeg,image/png,image/webp,image/gif"><?php if(setting('store_logo')):?><img class="upload-preview" src="../<?=h(setting('store_logo'))?>" alt="الشعار الحالي"><?php endif?></label><label>صورة البانر العلوي<input type="file" name="hero_image" accept="image/jpeg,image/png,image/webp,image/gif"><?php if(setting('hero_image')):?><img class="upload-preview" src="../<?=h(setting('hero_image'))?>" alt="البانر الحالي"><?php endif?></label><button class="gold">حفظ الإعدادات</button></form><p>الحد الأقصى لكل صورة 5 ميجابايت. الصيغ المدعومة JPG وPNG وWEBP وGIF.</p></main></body></html>